INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93100, '效忠阿斯泰洛·逐日王及其治世之光的象征。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93116, '让敌人知道我们的名字。让盟友缅怀我们的逝去。我们是洛萨之子。') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93200, '我要感谢角色扮演社群，特别是夜歌哨兵，让我的乌龟服体验如此有趣。——提珊德拉，诺达纳尔') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93201, '致所有被我偷袭后又逃跑的战争模式玩家：我不抱歉，我还会再干。今年我的长袜里大概会装满煤。——拉特尼斯，诺达纳尔') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93202, '祝你节日快乐、新年美好！愿游戏内外都充满家人相伴。用一次次偷袭带来欢笑与喜悦的泪水！——一级狂人们。——西斯塞蒂克，诺达纳尔') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93204, '我要感谢这个美好社群的每一个人，让乌龟服成为如此美妙的地方！我有太多难忘的回忆。冬幕节快乐！——斯普拉特莉西亚，诺达纳尔') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93205, '从萨多尔大桥到卡拉赞之塔，无论是暗如黑夜的术士还是沐浴圣光的圣骑士。在渡鸦呼唤的诺达纳尔，愿所有人共享冬幕快乐！——萨尔里内尔，诺达纳尔') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93206, '冬幕节的祝福致所有冒险者。分享你的增益，复活陌生人，让世界保持友善。——维瑞迪亚，诺达纳尔') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93207, '祝大家节日快乐！——安斯塔拉·银雨，诺达纳尔') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93208, '家人。——维鲁，琥珀郡') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93209, '无论我们在游戏和生活中选择何种模式（战争、软核、硬核），我们都组成一个社群，将慢而稳的精神延续下去。愿假期赐予你们毕业装备和温暖的经验帐篷！——甘克斯塔，琥珀郡') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93210, '侏儒的巧思流淌在矿道地铁的轨道上，以地下的和谐联结社群。无论你与谁同行、去向何方，没有侏儒就永远算不上家！——格雷戈里，荒芜的征服者，诺达纳尔') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93211, '家里有尖啸的鹰身女妖？非读那本厚厚的巨著不可？愿冬幕节的魅力赐你取胜的精神！——埃罗萨斯，诺达纳尔') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93212, '祝大家好运，旅途愉快 =) ——阿姆塞特，琥珀郡') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93213, '嘟嘟！——嘟嘟·麦克丁格斯') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93214, '祝大家圣诞快乐！——提兹，琥珀郡') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93215, '愿你的旅途充满友谊，任务满载惊奇，背包在你最需要时总多一瓶治疗药水。——神圣德鲁伊，泰尔阿比姆') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93216, '活动期间出售雪球世界首领的坦克服务，10金。——问问我能加啥，琥珀郡') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93217, '祝所有乌龟玩家节日快乐。注意安全，这个季节请靠近副本排队。——贝尔菲，琥珀郡') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93218, '你们都是一群可爱的人！我妈妈05年就在玩，跟我讲了好多可怕的故事。但我25级的巨魔牧师在我摸索期间得到了很多耐心。Lok''tar！——火腿吐司，琥珀郡') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93219, '祝大伙圣诞快乐，很高兴发现了这个服务器 :) 谢谢！——塞米泽') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93220, '祝你圣诞快乐、新年快乐，愿你在游戏与现实中通过无数小时努力应得的稀有掉落都到手！向所有人致以温暖的冬幕祝福！——尼克斯塔，琥珀郡') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
INSERT INTO `locales_item` (`entry`, `description_loc4`) VALUES (93221, '圣诞快乐，愿每个人的长袜都装满达拉然橙子！——古尔吉') ON DUPLICATE KEY UPDATE `description_loc4` = VALUES(`description_loc4`);
